import React, { useState, useEffect, useRef } from 'react';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';

const VILLES = ['Tunis','Sfax','Sousse','Monastir','Nabeul','Bizerte','Kairouan','Ariana','Ben Arous','Mahdia'];
const MODES = [
  { value: 'en_ligne',   label: '🌐 En ligne',   desc: 'Cours via Google Meet, Zoom...',   color: '#38bdf8', bg: 'rgba(56,189,248,0.1)'  },
  { value: 'presentiel', label: '🏫 Présentiel',  desc: 'Cours en face à face',             color: '#43e97b', bg: 'rgba(67,233,123,0.1)'  },
  { value: 'les_deux',   label: '🔀 Les deux',    desc: 'En ligne et présentiel',           color: '#6c63ff', bg: 'rgba(108,99,255,0.1)' },
];

function StatutBadge({ statut }) {
  const cfg = {
    en_attente: { bg: 'rgba(245,158,11,0.12)', color: '#f59e0b', label: '⏳ En attente' },
    approuvé:   { bg: 'rgba(67,233,123,0.12)',  color: '#43e97b', label: '✅ Approuvée'  },
    refusé:     { bg: 'rgba(255,101,132,0.12)', color: '#ff6584', label: '❌ Refusée'    },
  }[statut] || { bg: 'var(--surface2)', color: 'var(--text2)', label: statut };
  return (
    <span style={{ fontSize: '.7rem', fontWeight: 700, padding: '3px 10px', borderRadius: 20, background: cfg.bg, color: cfg.color }}>
      {cfg.label}
    </span>
  );
}

function Field({ label, icon, children, hint }) {
  return (
    <div style={{ marginBottom: 18 }}>
      <label style={{ display: 'flex', alignItems: 'center', gap: 6, fontSize: '.75rem', fontWeight: 700, color: 'var(--text2)', textTransform: 'uppercase', letterSpacing: '.07em', marginBottom: 7 }}>
        {icon && <span style={{ fontSize: '.9rem' }}>{icon}</span>}
        {label}
      </label>
      {children}
      {hint && <div style={{ fontSize: '.72rem', color: 'var(--text2)', marginTop: 5 }}>{hint}</div>}
    </div>
  );
}

/* ════════════════════════════════════════════════
   AVATAR UPLOAD
════════════════════════════════════════════════ */
function AvatarUpload({ photoUrl, nom, prenom, role, onUpload }) {
  const [dragging,  setDragging]  = useState(false);
  const [preview,   setPreview]   = useState(null);
  const [uploading, setUploading] = useState(false);
  const inputRef = useRef(null);

  const initials   = `${(prenom || '')[0] || ''}${(nom || '')[0] || ''}`.toUpperCase();
  const displaySrc = preview || (photoUrl ? `http://localhost:8001${photoUrl}` : null);

  const handleFile = async (file) => {
    if (role === 'admin') return;  // pas de photo pour l'admin
    if (!file || !file.type.startsWith('image/')) { alert('Image JPG/PNG/WEBP uniquement'); return; }

    const reader = new FileReader();
    reader.onload = e => setPreview(e.target.result);
    reader.readAsDataURL(file);

    setUploading(true);
    const fd = new FormData();
    fd.append('file', file);
    try {
      const route = role === 'professeur' ? '/api/professeurs/me/photo' : '/api/etudiants/me/photo';
      const res   = await api.post(route, fd, { headers: { 'Content-Type': 'multipart/form-data' } });
      onUpload?.(res.data.url);
    } catch {
      alert("Erreur lors de l'upload de la photo");
      setPreview(null);
    } finally {
      setUploading(false);
    }
  };

  const clickable = role !== 'admin';

  return (
    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 12 }}>
      <div
        style={{ position: 'relative', cursor: clickable ? 'pointer' : 'default' }}
        onClick={() => clickable && inputRef.current?.click()}
        onDragOver={e => { e.preventDefault(); if (clickable) setDragging(true); }}
        onDragLeave={() => setDragging(false)}
        onDrop={e => { e.preventDefault(); setDragging(false); if (clickable) handleFile(e.dataTransfer.files[0]); }}
      >
        <div style={{ width: 110, height: 110, borderRadius: '50%', border: dragging ? '3px solid #6c63ff' : '3px solid var(--border)', overflow: 'hidden', background: 'linear-gradient(135deg,#6c63ff,#ff6584)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '2.2rem', fontWeight: 700, color: '#fff', transition: 'all .2s' }}>
          {displaySrc ? <img src={displaySrc} alt="avatar" style={{ width: '100%', height: '100%', objectFit: 'cover' }} /> : (role === 'admin' ? '🛡️' : initials || '👤')}
        </div>
        {clickable && (
          <>
            <div style={{ position: 'absolute', inset: 0, borderRadius: '50%', background: 'rgba(0,0,0,0.45)', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', opacity: uploading ? 1 : 0, transition: 'opacity .2s' }}
              onMouseEnter={e => { if (!uploading) e.currentTarget.style.opacity = 1; }}
              onMouseLeave={e => { if (!uploading) e.currentTarget.style.opacity = 0; }}>
              <span style={{ fontSize: '1.4rem' }}>{uploading ? '⏳' : '📷'}</span>
              {!uploading && <span style={{ fontSize: '.6rem', color: '#fff', marginTop: 3, fontWeight: 600 }}>Changer</span>}
            </div>
            <div style={{ position: 'absolute', bottom: 4, right: 4, width: 28, height: 28, borderRadius: '50%', background: 'linear-gradient(135deg,#6c63ff,#8b5cf6)', border: '2px solid var(--card)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '.8rem' }}>📷</div>
          </>
        )}
      </div>
      <input ref={inputRef} type="file" hidden accept="image/jpeg,image/png,image/webp" onChange={e => handleFile(e.target.files[0])} />
      {clickable && <div style={{ fontSize: '.72rem', color: 'var(--text2)', textAlign: 'center' }}>Cliquez ou déposez une image<br />JPG, PNG · Max 5MB</div>}
    </div>
  );
}

/* ════════════════════════════════════════════════
   PAGE PRINCIPALE
════════════════════════════════════════════════ */
export default function Profile() {
  const { user } = useAuth();

  const [form, setForm] = useState({
    user_prenom: '', user_nom: '', email: '', ville: '', bio: '', telephone: '',
    niveau: '', tarifs_matieres: [], certificats: [], photo_url: null,
    mode_enseignement: 'presentiel', tarif_en_ligne: '', tarif_presentiel: '',
  });
  const [structure, setStructure]   = useState([]);
  const [loading,   setLoading]     = useState(true);
  const [saving,    setSaving]      = useState(false);
  const [saved,     setSaved]       = useState(false);
  const [demandes,  setDemandes]    = useState([]);

  const [showCertModal,    setShowCertModal]    = useState(false);
  const [newCert,          setNewCert]          = useState({ titre: '' });
  const [selectedFile,     setSelectedFile]     = useState(null);
  const [showDemandeModal, setShowDemandeModal] = useState(false);
  const [newDemande,       setNewDemande]       = useState({ nom_matiere: '', niveau_id: '' });
  const [submittingDemande,setSubmittingDemande]= useState(false);

  useEffect(() => { fetchProfileData(); }, [user]);

  /* ─── FIX : admin → pas de /referentiel/structure (401) ───────── */
  const fetchProfileData = async () => {
    if (!user) return;
    try {
      const route = user.role === 'professeur' ? '/api/professeurs/me'
                  : user.role === 'étudiant'   ? '/api/etudiants/me'
                  : '/api/auth/me';

      const requests = [api.get(route)];
      if (user.role !== 'admin') requests.push(api.get('/api/admin/referentiel/structure'));
      if (user.role === 'professeur') requests.push(api.get('/api/professeurs/me/demandes-matieres'));

      const results = await Promise.all(requests);
      const data    = results[0].data;
      const struct  = user.role !== 'admin' ? (results[1]?.data || []) : [];

      let email = data.email || user?.email || '';
      if (!email) {
        try { const r = await api.get('/api/auth/me'); email = r.data?.email || ''; } catch {}
      }

      setStructure(struct);
      setForm(prev => ({
        ...prev, ...data,
        user_prenom:       data.prenom      || data.user_prenom || user?.prenom || '',
        user_nom:          data.nom         || data.user_nom    || user?.nom    || '',
        email,
        ville:             data.ville       || '',
        telephone:         data.telephone   || '',
        bio:               data.bio         || '',
        niveau:            data.niveau      || '',
        photo_url:         data.photo_url   || null,
        certificats:       data.certificats || [],
        tarifs_matieres:   data.tarifs_matieres || [],
        mode_enseignement: data.mode_enseignement || 'presentiel',
        tarif_en_ligne:    data.tarif_en_ligne   != null ? data.tarif_en_ligne   : '',
        tarif_presentiel:  data.tarif_presentiel != null ? data.tarif_presentiel : '',
      }));

      if (user.role === 'professeur') {
        const idx = 2; // [0]=profil, [1]=structure, [2]=demandes
        if (results[idx]) setDemandes(results[idx].data);
      }
    } catch (e) {
      console.error('Erreur chargement profil', e);
    } finally {
      setLoading(false);
    }
  };

  const handleInput = (key, val) => setForm(f => ({ ...f, [key]: val }));

  const isSelected = (matId, nivId) =>
    form.tarifs_matieres?.some(t => t.matiere_id === matId && t.niveau_id === nivId);

  const handleToggleMatiere = (matId, nivId) => {
    let list = [...(form.tarifs_matieres || [])];
    if (isSelected(matId, nivId)) list = list.filter(t => !(t.matiere_id === matId && t.niveau_id === nivId));
    else list.push({ matiere_id: matId, niveau_id: nivId, tarif: 0 });
    setForm(f => ({ ...f, tarifs_matieres: list }));
  };

  const handleSave = async () => {
    setSaving(true);
    try {
      const route = user.role === 'professeur' ? '/api/professeurs/me'
                  : user.role === 'étudiant'   ? '/api/etudiants/me'
                  : '/api/auth/me';
      await api.put(route, {
        nom: form.user_nom, prenom: form.user_prenom,
        ville: form.ville, telephone: form.telephone, bio: form.bio,
        ...(user.role === 'étudiant' && { niveau: form.niveau }),
        ...(user.role === 'professeur' && {
          tarifs_complets:   form.tarifs_matieres,
          mode_enseignement: form.mode_enseignement,
          tarif_en_ligne:    form.tarif_en_ligne    !== '' ? parseFloat(form.tarif_en_ligne)    : null,
          tarif_presentiel:  form.tarif_presentiel  !== '' ? parseFloat(form.tarif_presentiel)  : null,
        }),
      });
      setSaved(true);
      setTimeout(() => setSaved(false), 3000);
    } catch { alert('Erreur lors de la sauvegarde'); }
    finally { setSaving(false); }
  };

  const handleCertUpload = async (e) => {
    e.preventDefault();
    const fd = new FormData();
    fd.append('titre', newCert.titre);
    fd.append('file', selectedFile);
    try {
      await api.post('/api/professeurs/me/certificats', fd, { headers: { 'Content-Type': 'multipart/form-data' } });
      setShowCertModal(false); setNewCert({ titre: '' }); setSelectedFile(null);
      fetchProfileData();
    } catch { alert('Erreur certificat'); }
  };

  const handleSubmitDemande = async (e) => {
    e.preventDefault();
    if (!newDemande.nom_matiere.trim() || !newDemande.niveau_id) { alert('Remplissez tous les champs'); return; }
    setSubmittingDemande(true);
    try {
      await api.post('/api/professeurs/me/demandes-matieres', { nom_matiere: newDemande.nom_matiere.trim(), niveau_id: parseInt(newDemande.niveau_id) });
      setShowDemandeModal(false); setNewDemande({ nom_matiere: '', niveau_id: '' });
      const res = await api.get('/api/professeurs/me/demandes-matieres');
      setDemandes(res.data);
    } catch (e) { alert('Erreur : ' + (e.response?.data?.detail || e.message)); }
    finally { setSubmittingDemande(false); }
  };

  const inp = { background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 11, color: 'var(--text)', padding: '11px 14px', fontSize: '.88rem', width: '100%', outline: 'none', boxSizing: 'border-box', transition: 'border-color .2s' };

  if (loading) return (
    <div style={{ padding: 60, textAlign: 'center', color: 'var(--text2)' }}>
      <div style={{ fontSize: '2rem', marginBottom: 12 }}>⏳</div>Chargement du profil...
    </div>
  );

  const isProfesseur = user?.role === 'professeur';
  const isEtudiant   = user?.role === 'étudiant';

  return (
    <div style={{ padding: 32, maxWidth: isProfesseur ? 1300 : 760, margin: '0 auto' }}>

      {/* HERO */}
      <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 24, overflow: 'hidden', marginBottom: 28 }}>
        <div style={{ height: 110, background: 'linear-gradient(135deg,rgba(108,99,255,.4),rgba(255,101,132,.25))', position: 'relative' }}>
          <div style={{ position: 'absolute', bottom: -50, left: 32 }}>
            <AvatarUpload photoUrl={form.photo_url} nom={form.user_nom} prenom={form.user_prenom} role={user?.role} onUpload={url => setForm(f => ({ ...f, photo_url: url }))} />
          </div>
        </div>
        <div style={{ padding: '58px 32px 24px', display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end' }}>
          <div>
            <h2 style={{ fontFamily: 'Syne', fontSize: '1.6rem', margin: '0 0 4px' }}>{form.user_prenom} {form.user_nom}</h2>
            <div style={{ display: 'flex', alignItems: 'center', gap: 10, flexWrap: 'wrap' }}>
              <span style={{ fontSize: '.82rem', color: 'var(--text2)', textTransform: 'capitalize' }}>
                {user?.role === 'professeur' ? '👨‍🏫' : user?.role === 'étudiant' ? '👨‍🎓' : '🛡️'} Compte {user?.role}
              </span>
              {form.ville && <span style={{ fontSize: '.8rem', color: 'var(--text2)' }}>📍 {form.ville}</span>}
              {isEtudiant && form.niveau && <span style={{ fontSize: '.75rem', fontWeight: 600, padding: '2px 9px', borderRadius: 20, background: 'rgba(108,99,255,0.1)', color: '#6c63ff' }}>🎓 {form.niveau}</span>}
              {isProfesseur && <span style={{ fontSize: '.75rem', fontWeight: 600, padding: '2px 9px', borderRadius: 20, background: MODES.find(m => m.value === form.mode_enseignement)?.bg || 'var(--surface2)', color: MODES.find(m => m.value === form.mode_enseignement)?.color || 'var(--text2)' }}>{MODES.find(m => m.value === form.mode_enseignement)?.label}</span>}
            </div>
          </div>
          <button onClick={handleSave} disabled={saving} style={{ padding: '10px 24px', background: saved ? 'linear-gradient(135deg,#43e97b,#38f9d7)' : 'linear-gradient(135deg,#6c63ff,#8b5cf6)', color: saved ? '#000' : '#fff', border: 'none', borderRadius: 12, fontWeight: 700, cursor: saving ? 'not-allowed' : 'pointer', fontSize: '.88rem', transition: 'all .3s', boxShadow: '0 4px 14px rgba(108,99,255,0.3)' }}>
            {saving ? '⏳ Enregistrement...' : saved ? '✅ Enregistré !' : '💾 Enregistrer'}
          </button>
        </div>
      </div>

      {/* CONTENU */}
      <div style={{ display: 'grid', gridTemplateColumns: isProfesseur ? '400px 1fr' : '1fr', gap: 24 }}>

        <div style={{ display: 'flex', flexDirection: 'column', gap: 20 }}>
          <Section title="👤 Mon Identité">
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 14 }}>
              <Field label="Prénom" icon="✏️"><input style={inp} value={form.user_prenom} onChange={e => handleInput('user_prenom', e.target.value)} placeholder="Votre prénom" /></Field>
              <Field label="Nom" icon="✏️"><input style={inp} value={form.user_nom} onChange={e => handleInput('user_nom', e.target.value)} placeholder="Votre nom" /></Field>
            </div>
            <Field label="Email" icon="✉️" hint="L'email ne peut pas être modifié">
              <div style={{ position: 'relative' }}>
                <input style={{ ...inp, opacity: .6, cursor: 'not-allowed', paddingRight: 40 }} value={form.email} readOnly />
                <span style={{ position: 'absolute', right: 12, top: '50%', transform: 'translateY(-50%)', fontSize: '.8rem' }}>🔒</span>
              </div>
            </Field>
            {user?.role !== 'admin' && (
              <>
                <Field label="Téléphone" icon="📞"><input style={inp} value={form.telephone} onChange={e => handleInput('telephone', e.target.value)} placeholder="+216 XX XXX XXX" /></Field>
                <Field label="Ville" icon="📍">
                  <select style={inp} value={form.ville} onChange={e => handleInput('ville', e.target.value)}>
                    <option value="">Sélectionner votre ville...</option>
                    {VILLES.map(v => <option key={v} value={v}>{v}</option>)}
                  </select>
                </Field>
              </>
            )}
            {isEtudiant && (
              <Field label="Niveau scolaire" icon="🎓" hint="Choisissez le niveau qui correspond à votre scolarité actuelle">
                <NiveauSelector value={form.niveau} onChange={val => handleInput('niveau', val)} />
              </Field>
            )}
          </Section>

          {(isEtudiant || isProfesseur) && (
            <Section title="📝 À propos de moi">
              <textarea style={{ ...inp, height: 120, resize: 'vertical' }} value={form.bio || ''}
                placeholder={isEtudiant ? "Parlez un peu de vous, vos objectifs scolaires..." : "Décrivez votre expérience, votre méthode d'enseignement..."}
                onChange={e => handleInput('bio', e.target.value)} />
            </Section>
          )}

          {isProfesseur && (
            <Section title="🎓 Mode d'enseignement">
              <div style={{ display: 'flex', flexDirection: 'column', gap: 8, marginBottom: 16 }}>
                {MODES.map(m => {
                  const active = form.mode_enseignement === m.value;
                  return (
                    <div key={m.value} onClick={() => handleInput('mode_enseignement', m.value)}
                      style={{ display: 'flex', alignItems: 'center', gap: 14, padding: '12px 14px', borderRadius: 12, cursor: 'pointer', border: active ? `2px solid ${m.color}` : '2px solid var(--border)', background: active ? m.bg : 'var(--surface2)', transition: 'all .18s' }}>
                      <div style={{ width: 18, height: 18, borderRadius: '50%', border: `2px solid ${active ? m.color : 'var(--text2)'}`, background: active ? m.color : 'transparent', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
                        {active && <div style={{ width: 7, height: 7, borderRadius: '50%', background: '#fff' }} />}
                      </div>
                      <div>
                        <div style={{ fontWeight: 700, fontSize: '.88rem', color: active ? m.color : 'var(--text)' }}>{m.label}</div>
                        <div style={{ fontSize: '.72rem', color: 'var(--text2)' }}>{m.desc}</div>
                      </div>
                    </div>
                  );
                })}
              </div>
              <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
                {(form.mode_enseignement === 'en_ligne' || form.mode_enseignement === 'les_deux') && (
                  <div style={{ background: 'rgba(56,189,248,0.07)', border: '1px solid rgba(56,189,248,0.2)', borderRadius: 11, padding: '12px 14px' }}>
                    <label style={{ fontSize: '.78rem', color: '#38bdf8', fontWeight: 700, display: 'block', marginBottom: 8 }}>🌐 Tarif en ligne</label>
                    <div style={{ display: 'flex', gap: 10, alignItems: 'center' }}>
                      <input type="number" min="0" step="0.5" style={{ ...inp, flex: 1 }} placeholder="Ex: 30" value={form.tarif_en_ligne} onChange={e => handleInput('tarif_en_ligne', e.target.value)} />
                      <span style={{ color: '#38bdf8', fontWeight: 700, whiteSpace: 'nowrap' }}>DT/h</span>
                    </div>
                  </div>
                )}
                {(form.mode_enseignement === 'presentiel' || form.mode_enseignement === 'les_deux') && (
                  <div style={{ background: 'rgba(67,233,123,0.07)', border: '1px solid rgba(67,233,123,0.2)', borderRadius: 11, padding: '12px 14px' }}>
                    <label style={{ fontSize: '.78rem', color: '#43e97b', fontWeight: 700, display: 'block', marginBottom: 8 }}>🏫 Tarif présentiel</label>
                    <div style={{ display: 'flex', gap: 10, alignItems: 'center' }}>
                      <input type="number" min="0" step="0.5" style={{ ...inp, flex: 1 }} placeholder="Ex: 40" value={form.tarif_presentiel} onChange={e => handleInput('tarif_presentiel', e.target.value)} />
                      <span style={{ color: '#43e97b', fontWeight: 700, whiteSpace: 'nowrap' }}>DT/h</span>
                    </div>
                  </div>
                )}
              </div>
            </Section>
          )}

          {isProfesseur && (
            <Section title="📜 Mes Diplômes & Certificats">
              <div style={{ display: 'flex', flexDirection: 'column', gap: 8, marginBottom: 12 }}>
                {form.certificats?.length === 0 && <div style={{ textAlign: 'center', padding: '20px', color: 'var(--text2)', fontSize: '.82rem' }}>Aucun diplôme ajouté</div>}
                {form.certificats?.map(c => (
                  <div key={c.id} style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '10px 14px', background: 'var(--surface2)', borderRadius: 10, border: '1px solid var(--border)' }}>
                    <span style={{ fontSize: '1.2rem' }}>{c.fichier_url?.endsWith('.pdf') ? '📄' : '🖼️'}</span>
                    <span style={{ fontWeight: 600, fontSize: '.85rem', flex: 1 }}>{c.titre}</span>
                    <a href={`http://localhost:8001${c.fichier_url}`} target="_blank" rel="noreferrer" style={{ color: '#6c63ff', fontSize: '.8rem', fontWeight: 600, textDecoration: 'none' }}>Consulter ↗</a>
                  </div>
                ))}
              </div>
              <button onClick={() => setShowCertModal(true)} style={{ width: '100%', border: '2px dashed rgba(108,99,255,0.3)', background: 'rgba(108,99,255,0.04)', color: '#6c63ff', padding: 12, borderRadius: 12, cursor: 'pointer', fontWeight: 600, fontSize: '.85rem' }}>
                + Ajouter un diplôme ou certificat
              </button>
            </Section>
          )}

          {isEtudiant && (
            <button onClick={handleSave} disabled={saving} style={{ padding: '14px', background: saved ? 'linear-gradient(135deg,#43e97b,#38f9d7)' : 'linear-gradient(135deg,#6c63ff,#8b5cf6)', color: saved ? '#000' : '#fff', border: 'none', borderRadius: 14, fontWeight: 700, cursor: saving ? 'not-allowed' : 'pointer', fontSize: '.95rem', transition: 'all .3s', boxShadow: '0 4px 20px rgba(108,99,255,0.3)' }}>
              {saving ? '⏳ Enregistrement...' : saved ? '✅ Profil enregistré !' : '💾 Enregistrer mon profil'}
            </button>
          )}
        </div>

        {isProfesseur && (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 20 }}>
            <Section title="📚 Mes Enseignements" action={
              <button onClick={() => setShowDemandeModal(true)} style={{ background: 'rgba(108,99,255,0.12)', color: '#6c63ff', border: '1px solid rgba(108,99,255,0.3)', padding: '7px 14px', borderRadius: 10, cursor: 'pointer', fontWeight: 600, fontSize: '.8rem' }}>+ Proposer une matière</button>
            }>
              {structure.map(dom => (
                <div key={dom.id} style={{ marginBottom: 24 }}>
                  <div style={{ color: 'var(--accent)', fontWeight: 800, fontSize: '.9rem', marginBottom: 12, paddingBottom: 8, borderBottom: '2px solid rgba(108,99,255,0.2)' }}>📂 {dom.nom.toUpperCase()}</div>
                  {dom.niveaux?.map(niv => (
                    <div key={niv.id} style={{ marginBottom: 14, background: 'var(--surface2)', borderRadius: 14, padding: '14px 16px', border: '1px solid var(--border)' }}>
                      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 10 }}>
                        <div style={{ fontWeight: 700, fontSize: '.88rem' }}>🎓 {niv.nom}</div>
                        <button onClick={() => { setNewDemande({ nom_matiere: '', niveau_id: niv.id }); setShowDemandeModal(true); }} style={{ background: 'none', border: '1px dashed var(--border)', color: 'var(--text2)', padding: '3px 9px', borderRadius: 8, cursor: 'pointer', fontSize: '.7rem', fontWeight: 600 }}>+ matière</button>
                      </div>
                      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(140px, 1fr))', gap: 7 }}>
                        {niv.matieres?.map(mat => {
                          const active = isSelected(mat.id, niv.id);
                          return (
                            <label key={mat.id} style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '8px 11px', borderRadius: 9, cursor: 'pointer', background: active ? 'rgba(108,99,255,0.12)' : 'var(--card)', border: active ? '1px solid rgba(108,99,255,0.4)' : '1px solid var(--border)', transition: 'all .15s' }}>
                              <input type="checkbox" checked={active} onChange={() => handleToggleMatiere(mat.id, niv.id)} style={{ accentColor: '#6c63ff', width: 14, height: 14, flexShrink: 0 }} />
                              <span style={{ fontSize: '.82rem', fontWeight: active ? 600 : 400, color: active ? '#6c63ff' : 'var(--text)' }}>{mat.nom}</span>
                            </label>
                          );
                        })}
                      </div>
                    </div>
                  ))}
                </div>
              ))}
              <button onClick={handleSave} disabled={saving} style={{ width: '100%', background: saved ? 'linear-gradient(135deg,#43e97b,#38f9d7)' : 'linear-gradient(135deg,#6c63ff,#8b5cf6)', color: saved ? '#000' : '#fff', border: 'none', padding: 13, borderRadius: 12, fontWeight: 700, cursor: 'pointer', fontSize: '.9rem', transition: 'all .3s' }}>
                {saving ? '⏳...' : saved ? '✅ Enregistré !' : '💾 Sauvegarder mes enseignements'}
              </button>
            </Section>

            {demandes.length > 0 && (
              <Section title="📋 Mes demandes de matières">
                <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
                  {demandes.map(d => (
                    <div key={d.id} style={{ background: 'var(--surface2)', padding: '10px 14px', borderRadius: 10, border: '1px solid var(--border)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                      <div><div style={{ fontWeight: 600, fontSize: '.88rem' }}>{d.nom_matiere}</div><div style={{ fontSize: '.73rem', color: 'var(--text2)', marginTop: 2 }}>Niveau : {d.nom_niveau}</div></div>
                      <StatutBadge statut={d.statut} />
                    </div>
                  ))}
                </div>
              </Section>
            )}
          </div>
        )}
      </div>

      {showCertModal && (
        <Modal title="📁 Nouveau Diplôme / Certificat" onClose={() => setShowCertModal(false)}>
          <form onSubmit={handleCertUpload} style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
            <Field label="Titre du diplôme"><input style={inp} placeholder="Ex: Master en Informatique..." value={newCert.titre} onChange={e => setNewCert({ titre: e.target.value })} required /></Field>
            <Field label="Fichier (PDF ou image)">
              <div style={{ border: '2px dashed var(--border)', borderRadius: 11, padding: '16px', textAlign: 'center', cursor: 'pointer' }} onClick={() => document.getElementById('cert-file').click()}>
                {selectedFile ? <div style={{ fontSize: '.85rem', color: '#43e97b', fontWeight: 600 }}>✅ {selectedFile.name}</div> : <div style={{ color: 'var(--text2)', fontSize: '.82rem' }}>Cliquer pour choisir<br /><span style={{ fontSize: '.72rem' }}>PDF, JPG, PNG</span></div>}
              </div>
              <input id="cert-file" type="file" hidden onChange={e => setSelectedFile(e.target.files[0])} required />
            </Field>
            <div style={{ display: 'flex', gap: 10 }}>
              <button type="submit" style={{ flex: 2, background: 'linear-gradient(135deg,#6c63ff,#8b5cf6)', color: '#fff', padding: 12, borderRadius: 10, border: 'none', fontWeight: 700, cursor: 'pointer' }}>Sauvegarder</button>
              <button type="button" onClick={() => setShowCertModal(false)} style={{ flex: 1, background: 'var(--surface2)', color: 'var(--text)', padding: 12, borderRadius: 10, border: '1px solid var(--border)', cursor: 'pointer' }}>Annuler</button>
            </div>
          </form>
        </Modal>
      )}

      {showDemandeModal && (
        <Modal title="💡 Proposer une nouvelle matière" onClose={() => setShowDemandeModal(false)}>
          <p style={{ fontSize: '.82rem', color: 'var(--text2)', marginBottom: 18, marginTop: 0 }}>Vous ne trouvez pas la matière que vous enseignez ? Proposez-la à l'administrateur.</p>
          <form onSubmit={handleSubmitDemande} style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
            <Field label="Nom de la matière"><input style={inp} placeholder="Ex: Robotique, Piano..." value={newDemande.nom_matiere} onChange={e => setNewDemande(d => ({ ...d, nom_matiere: e.target.value }))} required /></Field>
            <Field label="Niveau associé">
              <select style={inp} value={newDemande.niveau_id} onChange={e => setNewDemande(d => ({ ...d, niveau_id: e.target.value }))} required>
                <option value="">Sélectionner un niveau...</option>
                {structure.flatMap(dom => dom.niveaux?.map(niv => <option key={niv.id} value={niv.id}>[{dom.nom}] {niv.nom}</option>))}
              </select>
            </Field>
            <div style={{ background: 'rgba(245,158,11,0.08)', border: '1px solid rgba(245,158,11,0.2)', borderRadius: 10, padding: '10px 14px', fontSize: '.78rem', color: '#f59e0b' }}>⚠️ Votre demande sera examinée par l'administrateur avant d'être ajoutée au référentiel.</div>
            <div style={{ display: 'flex', gap: 10 }}>
              <button type="submit" disabled={submittingDemande} style={{ flex: 2, background: submittingDemande ? 'var(--border)' : 'linear-gradient(135deg,#6c63ff,#8b5cf6)', color: '#fff', padding: 12, borderRadius: 10, border: 'none', fontWeight: 700, cursor: submittingDemande ? 'not-allowed' : 'pointer' }}>
                {submittingDemande ? '⏳ Envoi...' : '📤 Envoyer la demande'}
              </button>
              <button type="button" onClick={() => setShowDemandeModal(false)} style={{ flex: 1, background: 'var(--surface2)', color: 'var(--text)', padding: 12, borderRadius: 10, border: '1px solid var(--border)', cursor: 'pointer' }}>Annuler</button>
            </div>
          </form>
        </Modal>
      )}
    </div>
  );
}

/* ════════════════════════════════════════════════
   NIVEAU SELECTOR — FIX : un seul return, pas de code mort
════════════════════════════════════════════════ */
const NIVEAUX_ACADEMIQUES = [
  { key: 'Primaire',   icon: '📚', desc: 'École primaire (1ère - 6ème)'  },
  { key: 'Collège',    icon: '📖', desc: '7ème - 9ème année de base'      },
  { key: 'Lycée',      icon: '🎒', desc: '1ère, 2ème, 3ème secondaire'    },
  { key: 'Université', icon: '🎓', desc: 'Licence, Master, Doctorat'      },
];

function NiveauSelector({ value, onChange }) {
  const [type, setType] = React.useState(() => {
    if (!value) return '';
    if (value === 'Professionnel') return 'professionnel';
    return 'academique';
  });

  React.useEffect(() => {
    if (!value) return;
    if (value === 'Professionnel') setType('professionnel');
    else setType('academique');
  }, [value]);

  const handleType = (t) => {
    setType(t);
    if (t === 'professionnel') onChange('Professionnel');
    else if (value === 'Professionnel') onChange('');
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>

      {/* Étape 1 */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10 }}>
        {[
          { key: 'academique',    icon: '🎓', label: 'Académique',    desc: 'Primaire, Collège, Lycée, Université',  color: '#6c63ff', bg: 'rgba(108,99,255,0.1)', border: 'rgba(108,99,255,0.35)' },
          { key: 'professionnel', icon: '💼', label: 'Professionnel', desc: 'Adulte en activité ou en reconversion', color: '#f59e0b', bg: 'rgba(245,158,11,0.1)',  border: 'rgba(245,158,11,0.35)'  },
        ].map(t => {
          const active = type === t.key;
          return (
            <div key={t.key} onClick={() => handleType(t.key)}
              style={{ padding: '14px 16px', borderRadius: 14, cursor: 'pointer', border: active ? `2px solid ${t.color}` : '2px solid var(--border)', background: active ? t.bg : 'var(--surface2)', transition: 'all .2s', boxShadow: active ? `0 4px 16px ${t.border}` : 'none' }}>
              <div style={{ fontSize: '1.4rem', marginBottom: 6 }}>{t.icon}</div>
              <div style={{ fontWeight: 700, fontSize: '.88rem', color: active ? t.color : 'var(--text)', marginBottom: 3 }}>{t.label}</div>
              <div style={{ fontSize: '.72rem', color: 'var(--text2)', lineHeight: 1.4 }}>{t.desc}</div>
              {active && <div style={{ marginTop: 8, display: 'inline-flex', alignItems: 'center', gap: 4, fontSize: '.7rem', fontWeight: 700, color: t.color, background: t.bg, padding: '2px 8px', borderRadius: 20 }}>✓ Sélectionné</div>}
            </div>
          );
        })}
      </div>

      {/* Étape 2 : sous-niveaux académiques */}
      {type === 'academique' && (
        <div style={{ padding: '16px', background: 'rgba(108,99,255,0.05)', border: '1px solid rgba(108,99,255,0.2)', borderRadius: 14, animation: 'fadeIn .2s ease' }}>
          <style>{`@keyframes fadeIn{from{opacity:0;transform:translateY(-6px)}to{opacity:1;transform:translateY(0)}}`}</style>
          <div style={{ fontSize: '.7rem', fontWeight: 800, color: '#6c63ff', textTransform: 'uppercase', letterSpacing: '.08em', marginBottom: 10 }}>📌 Choisissez votre niveau</div>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8 }}>
            {NIVEAUX_ACADEMIQUES.map(n => {
              const active = value === n.key;
              return (
                <button key={n.key} type="button" onClick={() => onChange(value === n.key ? '' : n.key)}
                  style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '11px 14px', borderRadius: 12, cursor: 'pointer', border: active ? '2px solid #6c63ff' : '1px solid var(--border)', background: active ? 'rgba(108,99,255,0.15)' : 'var(--surface2)', color: active ? '#6c63ff' : 'var(--text)', fontWeight: active ? 700 : 500, fontSize: '.85rem', transition: 'all .18s', textAlign: 'left', boxShadow: active ? '0 2px 12px rgba(108,99,255,0.25)' : 'none' }}>
                  <span style={{ fontSize: '1.1rem' }}>{n.icon}</span>
                  <div>
                    <div style={{ fontWeight: active ? 700 : 600 }}>{n.key}</div>
                    <div style={{ fontSize: '.68rem', color: 'var(--text2)', marginTop: 1 }}>{n.desc}</div>
                  </div>
                  {active && <span style={{ marginLeft: 'auto', width: 18, height: 18, borderRadius: '50%', background: '#6c63ff', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '.65rem', color: '#fff', flexShrink: 0 }}>✓</span>}
                </button>
              );
            })}
          </div>
          {value && value !== 'Professionnel' ? (
            <div style={{ marginTop: 10, display: 'flex', alignItems: 'center', gap: 8, padding: '8px 12px', background: 'rgba(108,99,255,0.08)', border: '1px solid rgba(108,99,255,0.2)', borderRadius: 10 }}>
              <span>🎓</span>
              <span style={{ fontSize: '.8rem', color: 'var(--text2)' }}>Niveau choisi :</span>
              <span style={{ fontSize: '.82rem', fontWeight: 700, color: '#6c63ff' }}>{value}</span>
              <button type="button" onClick={() => onChange('')} style={{ marginLeft: 'auto', background: 'none', border: 'none', color: 'var(--text2)', cursor: 'pointer', fontSize: '.75rem' }}>✕</button>
            </div>
          ) : (
            <div style={{ marginTop: 10, padding: '8px 12px', background: 'rgba(245,158,11,0.07)', border: '1px solid rgba(245,158,11,0.2)', borderRadius: 10, fontSize: '.77rem', color: '#f59e0b' }}>
              ⚠️ Veuillez sélectionner un niveau ci-dessus
            </div>
          )}
        </div>
      )}

      {/* Confirmation Professionnel */}
      {type === 'professionnel' && (
        <div style={{ padding: '12px 14px', background: 'rgba(245,158,11,0.07)', border: '1px solid rgba(245,158,11,0.2)', borderRadius: 12, display: 'flex', alignItems: 'center', gap: 10 }}>
          <span style={{ fontSize: '1.1rem' }}>💼</span>
          <div>
            <div style={{ fontWeight: 700, fontSize: '.82rem', color: '#f59e0b' }}>Profil professionnel</div>
            <div style={{ fontSize: '.73rem', color: 'var(--text2)', marginTop: 2 }}>Les professeurs proposeront des contenus adaptés aux adultes.</div>
          </div>
        </div>
      )}
    </div>
  );
}

function Section({ title, children, action }) {
  return (
    <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 }}>
        <h3 style={{ fontFamily: 'Syne', margin: 0, fontSize: '1rem', fontWeight: 800 }}>{title}</h3>
        {action}
      </div>
      {children}
    </div>
  );
}

function Modal({ title, onClose, children }) {
  return (
    <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.8)', backdropFilter: 'blur(4px)', zIndex: 1000, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 20 }}>
      <div style={{ background: 'var(--surface)', padding: 28, borderRadius: 22, width: '100%', maxWidth: 460, border: '1px solid var(--border)', boxShadow: '0 24px 80px rgba(0,0,0,0.5)', animation: 'modalIn .2s ease' }}>
        <style>{`@keyframes modalIn{from{opacity:0;transform:scale(.96)}to{opacity:1;transform:scale(1)}}`}</style>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 }}>
          <h3 style={{ margin: 0, fontFamily: 'Syne', fontSize: '1.05rem' }}>{title}</h3>
          <button onClick={onClose} style={{ width: 30, height: 30, borderRadius: 8, background: 'var(--surface2)', border: '1px solid var(--border)', cursor: 'pointer', color: 'var(--text)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>✕</button>
        </div>
        {children}
      </div>
    </div>
  );
}
